from pathlib import Path
import sys,json,numpy as np
from scipy.linalg import cho_factor,cho_solve
p=Path(__file__).resolve().parent;sys.path.insert(0,str(p.parent/'rain-corrected-coupled-reference'));from setup import m,r
parent=list(range(len(m.bs)))
def find(i):
 while parent[i]!=i:i=parent[i]
 return i
def join(a,b):parent[find(b)]=find(a)
def support(J):return [i for i in range(len(m.bs)) if np.any(J[:,i*6:i*6+6]) and np.any(m.M[i*6:i*6+6,i*6:i*6+6])]
freeblocks=[b for b in m.blocks if b['domain']=='free']
for b in freeblocks:
 bodies=support(b['J'])
 for i in bodies[1:]:join(bodies[0],i)
lookup={int(v):i for i,v in enumerate(r.free)};groups={};bodygroups={}
for b in freeblocks:
 bodies=support(b['J']);owners=set(find(i) for i in bodies);assert len(owners)==1
 owner=next(iter(owners));groups.setdefault(owner,[]).extend(lookup[i] for i in range(b['sl'].start,b['sl'].stop));bodygroups.setdefault(owner,set()).update(bodies)
groups={k:np.array(v,dtype=int) for k,v in groups.items()};owner_array=np.empty(len(r.free),dtype=int)
for k,ii in groups.items():owner_array[ii]=k
cross=owner_array[:,None]!=owner_array[None,:]
def validate(A):assert not np.any(A[cross]),'cross-articulation bilateral coupling'
validate(r.Hff);bad=r.Hff.copy();i,j=np.argwhere(cross)[0];bad[i,j]=bad[j,i]=1e-3
try:validate(bad)
except AssertionError:corruption=True
else:raise AssertionError('corruption accepted')
remaining_ownership=[]
for b in r.blocks:
 owners=sorted(set(find(i) for i in support(b['original']['J'])))
 remaining_ownership.append(dict(label=b['original']['label'],owners=owners))
factors={}
for mode in ['float64','float32','equilibrated-float32']:
 dtype=np.float64 if mode=='float64' else np.float32;factors[mode]=[]
 for owner,ii in groups.items():
  A=r.Hff[np.ix_(ii,ii)].astype(dtype);scale=np.sqrt(np.diag(A)) if mode=='equilibrated-float32' else np.ones(len(ii),dtype=dtype)
  factor=cho_factor(A/scale[:,None]/scale[None,:],lower=True);assert factor[0].dtype==dtype
  factors[mode].append((ii,scale,factor))
def solve(rhs,mode):
 dtype=np.float64 if mode=='float64' else np.float32;rhs=rhs.astype(dtype);out=np.zeros(len(rhs),dtype=dtype)
 for ii,scale,factor in factors[mode]:out[ii]=cho_solve(factor,rhs[ii]/scale)/scale
 return out.astype(np.float64)
rng=np.random.default_rng(20261006);cases=[('random-'+str(i),rng.normal(size=r.N)) for i in range(24)]
for arm in ['cold','capped']:cases.append((arm,np.load(p.parent/'rain-interior-global-budget'/(arm+'.npz'))['impulses'][r.remaining]))
records=[]
for name,y in cases:
 rhs=-(m.g[r.free]+r.Hfr@y);want=r.recover(y);vref=m.M@m.J.T@want
 for mode in factors:
  x=want.copy();x[r.free]=solve(rhs,mode);res=float(max(abs(r.Hff@x[r.free]-rhs)/(1+abs(rhs))));v=m.M@m.J.T@x;verr=float(max(abs(v-vref)/(1+abs(vref))));tol=1e-9 if mode=='float64' else 1e-5
  records.append(dict(case=name,mode=mode,free_residual=res,velocity_difference=verr,pass_screen=res<=tol and verr<=tol))
sizes=[len(v) for v in groups.values()];summary={mode:dict(cases=sum(v['mode']==mode for v in records),failed=sum(v['mode']==mode and not v['pass_screen'] for v in records),max_free_residual=max(v['free_residual'] for v in records if v['mode']==mode),max_velocity_difference=max(v['velocity_difference'] for v in records if v['mode']==mode)) for mode in factors}
result=dict(status='structural-factorization-verified',groups=[dict(owner=k,body_ids=[i+1 for i in sorted(bodygroups[k])],free_rows=ii.tolist()) for k,ii in groups.items()],sizes=sizes,dense_entries=len(r.free)**2,component_entries=sum(n*n for n in sizes),dense_cubic_work=len(r.free)**3,component_cubic_work=sum(n**3 for n in sizes),cross_coupling_corruption_rejected=corruption,remaining_ownership=remaining_ownership,summary=summary,records=records)
(p/'result.json').write_text(json.dumps(result,indent=2));print(json.dumps({k:v for k,v in result.items() if k not in ['groups','remaining_ownership','records']},indent=2));assert not summary['float64']['failed']
